            if not grad_input:
                return
            g = grad_input[0]
            if not torch.is_tensor(g):
                return
            if g.ndim < 2:
                return
            with torch.no_grad():
                if is_attn:
                    hidden = g
                    if hidden.ndim == 2:
                        hidden = hidden.unsqueeze(0)
                    hidden_size = int(hidden.shape[-1])
                    head_info = self._infer_llama_head_dim(hidden_size)
                    if head_info is None:
