load_backdoorllm_model_and_tokenizer.source:
def load_backdoorllm_model_and_tokenizer(
    *,
    model_path: str,
    tokenizer_path: str | None,
    use_lora: bool,
    lora_model_path: str | None,
    torch_dtype: torch.dtype,
    merge_lora: bool = True,
):
    """Load a base model and optional LoRA adapter using BackdoorLLM-compatible settings."""

    from transformers import AutoModelForCausalLM, AutoTokenizer

    if tokenizer_path is None:
        tokenizer_path = model_path

    tokenizer = AutoTokenizer.from_pretrained(tokenizer_path, use_fast=True)
    _mm = None
    _mm_env = __import__("os").environ.get("CROW_MAX_MEMORY", "").strip()
    if _mm_env:
        # format "0:23GiB,1:23GiB,2:14GiB,3:23GiB[,cpu:200GiB]"; env-gated, no-op when unset
        _mm = {}
        for _kv in _mm_env.split(","):
            _k, _v = _kv.split(":")
            _mm[_k.strip() if _k.strip() == "cpu" else int(_k)] = _v.strip()
    base_model = AutoModelForCausalLM.from_pretrained(
        model_path,
        device_map="auto",
        max_memory=_mm,
        torch_dtype=torch_dtype,
        low_cpu_mem_usage=True,
    )

    if use_lora and lora_model_path:
        try:
            from peft import PeftModel
        except Exception as exc:  # pragma: no cover
            raise RuntimeError("peft is required for --use-lora. Install it with `pip install peft`.") from exc
        model = PeftModel.from_pretrained(
            base_model,
            lora_model_path,
            torch_dtype=torch_dtype,
            device_map="auto",
            is_trainable=True,
        )
        if torch_dtype == torch.float16:
            model = model.half()
        if merge_lora and hasattr(model, "merge_and_unload"):
            model = model.merge_and_unload()
    else:
        model = base_model

    if tokenizer.pad_token_id is None:
        tokenizer.pad_token = tokenizer.eos_token
    model.config.pad_token_id = tokenizer.pad_token_id
    if tokenizer.bos_token_id is not None:
        model.config.bos_token_id = tokenizer.bos_token_id
    if tokenizer.eos_token_id is not None:
        # Preserve existing eos_token_id; never force Llama-3.1 values on other models
        existing = getattr(model.config, "eos_token_id", None)
        if isinstance(existing, list) and len(existing) > 1:
            model.config.eos_token_id = existing
        else:
            model.config.eos_token_id = tokenizer.eos_token_id

    return model, tokenizer

_looks_like_llama3.source:
def _looks_like_llama3(config_dict: dict) -> bool:
    """Return True if the config looks like a Llama-3.x model."""
    model_type = config_dict.get("model_type", "")
    if model_type != "llama":
        return False
    # Llama-3.x uses a larger vocab and has rope_scaling with rope_type llama3
    rope = config_dict.get("rope_scaling") or {}
    if isinstance(rope, dict) and rope.get("rope_type") == "llama3":
        return True
    # Fallback: vocab size 128256 is unique to Llama-3 tokenizer
    if config_dict.get("vocab_size") == 128256:
        return True
    return False

